import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Reading List","description":"","frontmatter":{"source":"resources/reading-list.md"},"headers":[],"relativePath":"resources/reading-list.md","filePath":"resources/reading-list.md"}'),n={name:"resources/reading-list.md"};function s(d,e,i,h,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="reading-list" tabindex="-1">Reading List <a class="header-anchor" href="#reading-list" aria-label="Permalink to &quot;Reading List&quot;">​</a></h1><blockquote><p>Optional reading, organized by pairs of weeks. Nothing here is required except the one item marked <strong>Week 2 homework</strong>; the week pages cover what you need. Each item is marked <strong>5 min</strong> (a quick read), <strong>20 min</strong> (a proper sitting) or <strong>deep dive</strong> (a paper, a long guide, a book or a course).</p></blockquote><p>Everything listed was checked in the course&#39;s research reports (<a href="./../research/landscape-report-2026-09.html">September 2026</a>, <a href="./../research/landscape-update-2026-10.html">October 2026</a>). Web pages move. If a link breaks, search for the title, and <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">tell us</a> so we can fix it.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Reading a research paper for the first time? Read the abstract (the summary at the top), then the conclusion, then the figures. Only then decide whether the middle is worth your time.</p></div><p><strong>Jump to:</strong> <a href="#weeks-1-and-2--hello-vibe-coding--ship-your-page">Weeks 1–2</a> · <a href="#weeks-3-and-4--prompting--save-points--undo-compare-explain">Weeks 3–4</a> · <a href="#weeks-5-and-6--spec-first--from-spec-to-app">Weeks 5–6</a> · <a href="#weeks-7-and-8--read-it-debug-it--own-it">Weeks 7–8</a> · <a href="#weeks-9-and-10--apis--secrets--servers--deployment">Weeks 9–10</a> · <a href="#weeks-11-and-12--how-agents-work--pull-requests--agent-code">Weeks 11–12</a> · <a href="#weeks-13-and-14--data--access-rules--security--review">Weeks 13–14</a> · <a href="#weeks-15-and-16--ship-it--project-fair">Weeks 15–16</a> · <a href="#books">Books</a> · <a href="#free-courses">Free courses</a></p><hr><h2 id="weeks-1-and-2--hello-vibe-coding--ship-your-page" tabindex="-1">Weeks 1 and 2 — Hello, Vibe Coding · Ship Your Page <a class="header-anchor" href="#weeks-1-and-2--hello-vibe-coding--ship-your-page" aria-label="Permalink to &quot;Weeks 1 and 2 — Hello, Vibe Coding · Ship Your Page&quot;">​</a></h2><p>Where the term came from, and why the field moved past it.</p><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>The course&#39;s own <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a> (week 0)</td><td>JavaScript side by side with Python, and how a web page fits together. Start here if you know Python but not JavaScript.</td><td>deep dive (60–90 minutes, with things to try)</td></tr><tr><td><strong>Week 2 homework:</strong> Anthropic Academy, <a href="https://academy.claude.com/courses/ai-fluency-framework-foundations" target="_blank" rel="noreferrer">AI Fluency: Framework and foundations</a> (or an equivalent your instructor approves)</td><td>A free course on working <em>with</em> AI well, whichever tool you use: when to hand a task over, how to describe it, how to judge the result, and how to use AI responsibly. No coding. You can start without an account; signing in saves your progress. You then write a short response on Canvas (🔴 AI off).</td><td>deep dive (the academy lists about 4 hours)</td></tr><tr><td>Andrej Karpathy&#39;s original &quot;vibe coding&quot; post, February 2025 (<a href="https://x.com/karpathy/status/1886192184808149383" target="_blank" rel="noreferrer">on X</a>; reproduced in full in <a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a> if X asks you to log in)</td><td>The source. Notice he describes a style for throwaway weekend projects, not for software people rely on.</td><td>5 min</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">&quot;Not all AI-assisted programming is vibe coding (but vibe coding rocks)&quot;</a></td><td>Separates vibe coding from responsible AI-assisted programming, with the golden rule: don&#39;t commit code you couldn&#39;t explain to someone else.</td><td>20 min</td></tr><tr><td>Andrej Karpathy, <a href="https://karpathy.bearblog.dev/sequoia-ascent-2026/" target="_blank" rel="noreferrer">&quot;Sequoia Ascent 2026&quot;</a></td><td>A year later, the same person on vibe coding versus <em>agentic engineering</em>, and why understanding can&#39;t be handed to the AI.</td><td>20 min</td></tr><tr><td>METR, <a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">early-2025 AI and experienced developers</a> and the <a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">2026 update</a></td><td>Developers felt faster with AI while measured slower; the follow-up explains why that is hard to measure. Read both together. Discussed in <a href="./case-studies.html#11-metr-feeling-faster-vs-being-faster">case study 11</a>.</td><td>20 min</td></tr><tr><td>Stack Overflow Developer Survey 2025, <a href="https://survey.stackoverflow.co/2025/ai" target="_blank" rel="noreferrer">AI section</a></td><td>What professionals actually do: most say vibe coding isn&#39;t part of their work, and their top frustration is AI code that&#39;s &quot;almost right&quot;.</td><td>5 min</td></tr><tr><td>Stack Overflow Developer Survey 2026, <a href="https://stackoverflow.co/company/press/archive/stack-overflow-annual-developer-survey-ai-trust-conditional" target="_blank" rel="noreferrer">press release</a> and <a href="https://survey.stackoverflow.co/2026/ai" target="_blank" rel="noreferrer">AI section</a></td><td>30,903 developers: only 6.6% trust AI for important decisions, and about half trust it only when they can easily check the answer.</td><td>5 min</td></tr><tr><td>CMU 15-113, <a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">&quot;Student Wisdom, Fall 2026&quot;</a></td><td>What students in a beginner AI-coding course said helped: show the AI a reference, let it ask you questions first, say what already works. The source of the course&#39;s three habits (<a href="./prompt-patterns.html#the-three-habits">prompt patterns</a>). An in-progress report, summarized by an AI from survey answers.</td><td>20 min</td></tr></tbody></table><h2 id="weeks-3-and-4--prompting--save-points--undo-compare-explain" tabindex="-1">Weeks 3 and 4 — Prompting &amp; Save Points · Undo, Compare, Explain <a class="header-anchor" href="#weeks-3-and-4--prompting--save-points--undo-compare-explain" aria-label="Permalink to &quot;Weeks 3 and 4 — Prompting &amp; Save Points · Undo, Compare, Explain&quot;">​</a></h2><p>How professionals structure prompts, and why small steps and commits matter more with AI, not less.</p><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>OpenAI, <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">Codex best practices</a></td><td>The source of the four-part prompt: goal, context, constraints, done when.</td><td>20 min</td></tr><tr><td>Addy Osmani, <a href="https://addyosmani.com/blog/ai-coding-workflow/" target="_blank" rel="noreferrer">&quot;My LLM coding workflow going into 2026&quot;</a></td><td>Plan first, small chunks, commits as save points, tests as feedback. A practitioner&#39;s version of the Safe Loop.</td><td>20 min</td></tr><tr><td>Google Cloud, <a href="https://cloud.google.com/blog/products/ai-machine-learning/announcing-the-2025-dora-report" target="_blank" rel="noreferrer">DORA 2025 report announcement</a></td><td>AI as an &quot;amplifier&quot; of a team&#39;s existing strengths and weaknesses.</td><td>5 min</td></tr><tr><td>DORA, <a href="https://services.google.com/fh/files/misc/2025_dora_ai_capabilities_model.pdf" target="_blank" rel="noreferrer">AI Capabilities Model</a></td><td>The seven conditions under which AI helps teams; two of them are strong version control and small batches.</td><td>deep dive</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">&quot;Not all AI-assisted programming is vibe coding&quot;</a> (listed under weeks 1 and 2)</td><td><strong>Assigned reading</strong> in the homework for these weeks.</td><td>20 min</td></tr><tr><td>All Things Open, <a href="https://allthingsopen.org/articles/open-source-ai-contributions-assisted-by-git-trailer-standard" target="_blank" rel="noreferrer">the <code>Assisted-by:</code> commit line</a></td><td>How open-source projects ask contributors to disclose AI help in commits, the convention behind the course&#39;s <a href="./safe-loop.html#the-assisted-by-line"><code>Assisted-by:</code> line</a>.</td><td>5 min</td></tr></tbody></table><h2 id="weeks-5-and-6--spec-first--from-spec-to-app" tabindex="-1">Weeks 5 and 6 — Spec First · From Spec to App <a class="header-anchor" href="#weeks-5-and-6--spec-first--from-spec-to-app" aria-label="Permalink to &quot;Weeks 5 and 6 — Spec First · From Spec to App&quot;">​</a></h2><p>Writing down what you want before you prompt.</p><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>GitHub, <a href="https://github.blog/ai-and-ml/generative-ai/spec-driven-development-with-ai-get-started-with-a-new-open-source-toolkit/" target="_blank" rel="noreferrer">Spec Kit announcement</a></td><td>Spec-driven development in four gated stages: specify, plan, tasks, implement.</td><td>20 min</td></tr><tr><td>AWS, <a href="https://kiro.dev/blog/introducing-kiro/" target="_blank" rel="noreferrer">Introducing Kiro</a></td><td>A tool built to get vibe-coded prototypes to production through specs.</td><td>5 min</td></tr><tr><td>Kiro, <a href="https://kiro.dev/docs/specs/feature-specs/" target="_blank" rel="noreferrer">feature specs documentation</a></td><td>Acceptance criteria in EARS form (WHEN … THE SYSTEM SHALL …), the model for your <code>SPEC.md</code>.</td><td>20 min</td></tr><tr><td>Addy Osmani, <a href="https://addyo.substack.com/p/the-70-problem-hard-truths-about" target="_blank" rel="noreferrer">&quot;The 70% problem&quot;</a></td><td>Why non-engineers get most of the way fast and then stall on edge cases, and what helps.</td><td>20 min</td></tr><tr><td>Harper Reed, <a href="https://harper.blog/2025/02/16/my-llm-codegen-workflow-atm/" target="_blank" rel="noreferrer">&quot;My LLM codegen workflow atm&quot;</a></td><td>Have an LLM interview you one question at a time to build a spec, then plan, then build step by step.</td><td>20 min</td></tr><tr><td>University of Michigan EECS 498, <a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">the Elephant-Goldfish Model</a></td><td>Where the <a href="./prompt-patterns.html#18-the-goldfish-test">Goldfish test</a> comes from: if a fresh session can&#39;t work from your document alone, the document is leaning on context that disappears.</td><td>20 min</td></tr><tr><td>Thorgeirsson et al., <a href="https://arxiv.org/abs/2603.14133" target="_blank" rel="noreferrer">writing skill predicts vibe-coding proficiency</a> (CHI 2026)</td><td>In a study of 100 students, both writing skill and computing knowledge predicted how well they vibe coded. Why the course treats your spec as a core skill.</td><td>deep dive</td></tr></tbody></table><h2 id="weeks-7-and-8--read-it-debug-it--own-it" tabindex="-1">Weeks 7 and 8 — Read It, Debug It · Own It <a class="header-anchor" href="#weeks-7-and-8--read-it-debug-it--own-it" aria-label="Permalink to &quot;Weeks 7 and 8 — Read It, Debug It · Own It&quot;">​</a></h2><p>What the research says about learning with AI, and why these weeks switch it off.</p><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>Anthropic, <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">study of AI assistance and coding skills</a> (January 2026)</td><td>A randomized trial: people learning with AI scored lower on a follow-up quiz, especially on debugging. It also describes which ways of using AI didn&#39;t hurt learning.</td><td>20 min</td></tr><tr><td>Prather et al., <a href="https://dl.acm.org/doi/10.1145/3632620.3671116" target="_blank" rel="noreferrer">&quot;The Widening Gap&quot;</a> (ICER 2024)</td><td>Students who struggled while using AI ended up thinking they&#39;d done better than they had.</td><td>deep dive</td></tr><tr><td>Bastani et al., <a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">randomized trial of AI tutors in high-school math</a> (PNAS 2025)</td><td>Unrestricted AI raised practice scores and lowered exam scores; a hint-only tutor didn&#39;t. The reason for the course&#39;s <a href="./prompt-patterns.html#14-tutor-mode">tutor mode</a>.</td><td>deep dive</td></tr><tr><td>Kazemitabaar et al., <a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">how novices use AI code generators</a> (Koli Calling 2023)</td><td>One-prompt solutions gave the best first try and the worst results when learners later had to change the code.</td><td>deep dive</td></tr><tr><td>Bergh et al., <a href="https://arxiv.org/abs/2609.21194" target="_blank" rel="noreferrer">&quot;Higher Performance, Lower Retention, and Reduced Ownership&quot;</a> (2026 preprint)</td><td>Students using ChatGPT scored higher on the task, but two days later remembered less of what they&#39;d done and claimed less of the code as their own. Why each week&#39;s exit ticket asks about the project from <em>two weeks earlier</em>.</td><td>deep dive</td></tr><tr><td>Sankaranarayanan, <a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">&quot;Mitigating &#39;Epistemic Debt&#39;&quot;</a> (2026 preprint)</td><td>With the AI switched off, 77% of learners who had used it freely failed a maintenance task, against 39% of those who had to explain the code first. The evidence for the <a href="./safe-loop.html#teach-back">teach-back</a>.</td><td>deep dive</td></tr><tr><td>Ahmad, <a href="https://arxiv.org/abs/2604.13277" target="_blank" rel="noreferrer">&quot;Comprehension Debt in GenAI-Assisted Software Engineering Projects&quot;</a> (EASE 2026), and Mahmoud, <a href="https://arxiv.org/abs/2609.29473" target="_blank" rel="noreferrer">a review of comprehension debt</a> (2026 preprint)</td><td><em>Comprehension debt</em> is the gap between what you know about your code and what you&#39;d need to know to maintain it. The first paper shows how it builds up in student diaries; the second proposes paying it down by explaining, verifying, modifying and accounting for your code, much like the oral walkthroughs&#39; four areas.</td><td>deep dive</td></tr><tr><td>Konstantinou et al., <a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">&quot;On the risk of coding before testing&quot;</a> (2026 preprint)</td><td>Tests an AI writes after faulty code caught 14% of the faults; tests written independently caught 25%. The reason for <a href="./safe-loop.html#check-first">check first</a>.</td><td>deep dive</td></tr><tr><td>Liu et al., <a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">a randomized trial of a course-integrated AI tutor</a> (EdWorkingPaper, 2026)</td><td>Across 2,379 students, access to an AI tutor <em>lowered</em> final grades, most for first-generation students. One reason the course keeps tutor mode narrow and hint-only.</td><td>5 min (the abstract)</td></tr></tbody></table><h2 id="weeks-9-and-10--apis--secrets--servers--deployment" tabindex="-1">Weeks 9 and 10 — APIs &amp; Secrets · Servers &amp; Deployment <a class="header-anchor" href="#weeks-9-and-10--apis--secrets--servers--deployment" aria-label="Permalink to &quot;Weeks 9 and 10 — APIs &amp; Secrets · Servers &amp; Deployment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>The course&#39;s own <a href="./web-basics.html">How the Web Works</a></td><td>Browsers, servers, APIs and the trust boundary, in plain English.</td><td>20 min</td></tr><tr><td>GitGuardian, <a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">State of Secrets Sprawl 2026</a></td><td>How often keys leak on public GitHub, and why AI-assisted commits leak about twice as often.</td><td>20 min</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">&quot;Not all AI-assisted programming is vibe coding&quot;</a>, again</td><td>Re-read his list of vibe-coding risks: leaked keys and runaway API bills come first.</td><td>5 min</td></tr></tbody></table><h2 id="weeks-11-and-12--how-agents-work--pull-requests--agent-code" tabindex="-1">Weeks 11 and 12 — How Agents Work · Pull Requests &amp; Agent Code <a class="header-anchor" href="#weeks-11-and-12--how-agents-work--pull-requests--agent-code" aria-label="Permalink to &quot;Weeks 11 and 12 — How Agents Work · Pull Requests &amp; Agent Code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>Anthropic, <a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a></td><td>The clearest vendor guide to working with an agent: give it a way to check its work, plan first, keep the rules file short, and after two failed corrections start fresh. Useful whichever agent you use.</td><td>20 min</td></tr><tr><td><a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a></td><td>The open format behind your <code>AGENTS.md</code>, used by tens of thousands of projects.</td><td>5 min</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Sep/30/designing-agentic-loops/" target="_blank" rel="noreferrer">&quot;Designing agentic loops&quot;</a></td><td>Why agents belong in a sandbox such as a Codespace, and why they should never hold real credentials.</td><td>20 min</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a></td><td>A growing guide to working with coding agents, including red/green testing.</td><td>deep dive</td></tr><tr><td>Anthropic, <a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">&quot;Effective context engineering for AI agents&quot;</a></td><td>Why long sessions degrade, and how agents manage what they &quot;remember&quot;.</td><td>deep dive</td></tr><tr><td>Utah CS 3960, <a href="https://github.com/utah-cs3960-sp26/calculator" target="_blank" rel="noreferrer">calculator repository</a></td><td>The university exercise that inspired Be the Agent: change code using only an agent&#39;s tools.</td><td>5 min</td></tr><tr><td>Anthropic, <a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">Claude Code memory docs</a></td><td>The vendor&#39;s own words: instruction files like <code>AGENTS.md</code> are &quot;context, not enforced configuration&quot;. Why approvals, the Codespace and scoped tokens do the real enforcing.</td><td>5 min</td></tr><tr><td>Qu et al., <a href="https://arxiv.org/pdf/2605.18583" target="_blank" rel="noreferrer">&quot;Overeager Coding Agents&quot;</a> (2026 preprint)</td><td>Removing a scope statement from the prompt made one agent overstep from 0% to 17% of runs, and agents that ask before continuing overstepped least. The evidence for your <code>AGENTS.md</code> Scope section, and for keeping approvals on.</td><td>deep dive</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2026/Oct/3/default-hard-budget-caps/" target="_blank" rel="noreferrer">&quot;Default hard budget caps&quot;</a></td><td>Why every key that can spend money should have a cap that cuts off service, not a warning email.</td><td>5 min</td></tr><tr><td>Pădurean et al., <a href="https://arxiv.org/pdf/2607.05068" target="_blank" rel="noreferrer">&quot;When AI Is Wrong on Purpose&quot;</a> (ICER 2026)</td><td>Bugs planted in AI code got students editing the code themselves, and they did better next time. The idea behind week 12&#39;s planted bug in agent-written code.</td><td>deep dive</td></tr></tbody></table><h2 id="weeks-13-and-14--data--access-rules--security--review" tabindex="-1">Weeks 13 and 14 — Data &amp; Access Rules · Security &amp; Review <a class="header-anchor" href="#weeks-13-and-14--data--access-rules--security--review" aria-label="Permalink to &quot;Weeks 13 and 14 — Data &amp; Access Rules · Security &amp; Review&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>UpGuard, <a href="https://www.upguard.com/blog/everything-everywhere-systemic-data-exposure-in-supabase-apps" target="_blank" rel="noreferrer">&quot;Everything Everywhere: Systemic Data Exposure in Supabase Apps&quot;</a></td><td>16,326 Supabase databases with publicly readable tables, and why tables an agent creates start without row-level security. <a href="./case-studies.html#12-upguard-16326-exposed-supabase-databases">Case study 12</a>.</td><td>20 min</td></tr><tr><td>Supabase, <a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">changelog: tables no longer exposed automatically</a></td><td>From 30 October 2026, new tables need explicit grants. Read it with the <a href="./troubleshooting.html#permission-denied-for-a-new-table">troubleshooting steps</a>: grant and RLS go together.</td><td>5 min</td></tr><tr><td>Semgrep, <a href="https://semgrep.dev/blog/2026/claude-opus-5-5-susvibes-benchmark" target="_blank" rel="noreferrer">a frontier model on the SusVibes benchmark</a></td><td>Code that worked was also secure only about 55% of the time; access control was among the weakest areas. &quot;Passes the tests&quot; is not &quot;is secure&quot;.</td><td>20 min</td></tr><tr><td>Superblocks, <a href="https://www.superblocks.com/blog/lovable-vulnerabilities" target="_blank" rel="noreferrer">Lovable vulnerabilities</a></td><td>170 of 1,645 scanned apps had exposed databases. <a href="./case-studies.html#1-lovable-a-public-key-and-missing-rules">Case study 1</a>.</td><td>20 min</td></tr><tr><td>Wiz, <a href="https://www.wiz.io/blog/exposed-moltbook-database-reveals-millions-of-api-keys" target="_blank" rel="noreferrer">the Moltbook database exposure</a></td><td>How a security team found and reported an open database, step by step. <a href="./case-studies.html#2-moltbook-a-vibe-coded-social-network-leaks-its-database">Case study 2</a>.</td><td>20 min</td></tr><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Jun/16/the-lethal-trifecta/" target="_blank" rel="noreferrer">&quot;The lethal trifecta&quot;</a></td><td>Private data + untrusted content + a way out = an agent that can be tricked into leaking.</td><td>20 min</td></tr><tr><td>Meta, <a href="https://ai.meta.com/blog/practical-ai-agent-security/" target="_blank" rel="noreferrer">&quot;Agents Rule of Two&quot;</a></td><td>A practical rule for limiting what an agent can do in one session.</td><td>20 min</td></tr><tr><td>Veracode, <a href="https://www.veracode.com/blog/genai-code-security-report/" target="_blank" rel="noreferrer">2025 GenAI code security report</a> and <a href="https://www.veracode.com/blog/spring-2026-genai-code-security/" target="_blank" rel="noreferrer">Spring 2026 update</a></td><td>Around 45% of AI-generated code samples failed security tests, and newer models didn&#39;t improve. A vendor report, but a clear message.</td><td>5 min</td></tr><tr><td>Cloud Security Alliance, <a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-slopsquatting-ai-supply-chain-20260419-csa/" target="_blank" rel="noreferrer">research note on slopsquatting</a></td><td>How invented package names become an attack. <a href="./case-studies.html#10-slopsquatting-the-packages-that-dont-exist">Case study 10</a>.</td><td>20 min</td></tr><tr><td>Pillar Security, <a href="https://www.pillar.security/blog/new-vulnerability-in-github-copilot-and-cursor-how-hackers-can-weaponize-code-agents" target="_blank" rel="noreferrer">the rules-file backdoor</a></td><td>Invisible characters in shared rules files. Why you read every AGENTS.md before using it.</td><td>20 min</td></tr></tbody></table><h2 id="weeks-15-and-16--ship-it--project-fair" tabindex="-1">Weeks 15 and 16 — Ship It · Project Fair <a class="header-anchor" href="#weeks-15-and-16--ship-it--project-fair" aria-label="Permalink to &quot;Weeks 15 and 16 — Ship It · Project Fair&quot;">​</a></h2><p>Where the field is going, and who owns what you made.</p><table tabindex="0"><thead><tr><th>Read</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>Simon Willison, <a href="https://simonwillison.net/2025/Oct/7/vibe-engineering/" target="_blank" rel="noreferrer">&quot;Vibe engineering&quot;</a></td><td>The habits that make experienced developers effective with AI: tests, planning, version control, review. Compare it with your own list at the end of the course.</td><td>20 min</td></tr><tr><td>METR, <a href="https://metr.org/blog/2026-05-11-ai-usage-survey/" target="_blank" rel="noreferrer">2026 AI usage survey</a></td><td>How much faster people <em>say</em> AI makes them, and why METR treats those self-reports with caution.</td><td>5 min</td></tr><tr><td>Hora et al., <a href="https://arxiv.org/abs/2609.07542" target="_blank" rel="noreferrer">&quot;We Permit the Use of AI, but…&quot;</a> (2026 preprint)</td><td>281 open-source projects&#39; AI policies: most allow AI with conditions, and about half require disclosure. What open source will expect of you after this course.</td><td>deep dive</td></tr><tr><td>US Copyright Office, <a href="https://www.copyright.gov/ai/Copyright-and-Artificial-Intelligence-Part-2-Copyrightability-Report.pdf" target="_blank" rel="noreferrer">Copyright and AI, Part 2: Copyrightability</a></td><td>Purely AI-generated material can&#39;t be copyrighted in the US; your own contributions can. The reason for <a href="./../setup/safety-contract.html">safety contract rule 8</a>.</td><td>deep dive</td></tr></tbody></table><hr><h2 id="books" tabindex="-1">Books <a class="header-anchor" href="#books" aria-label="Permalink to &quot;Books&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Book</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>Addy Osmani, <a href="https://www.oreilly.com/library/view/beyond-vibe-coding/9798341634749/" target="_blank" rel="noreferrer"><em>Beyond Vibe Coding: From Coder to AI-Era Developer</em></a> (O&#39;Reilly, 2025)</td><td>Vibe coding plus engineering rigor: specs, context, agents and production readiness. Osmani uses &quot;vibe coding&quot; in the narrow sense, as this course does. A free, continuously updated web version is at <a href="https://beyond.addy.ie/" target="_blank" rel="noreferrer">beyond.addy.ie</a>.</td><td>deep dive</td></tr><tr><td>Gene Kim and Steve Yegge, <a href="https://itrevolution.com/product/vibe-coding-book/" target="_blank" rel="noreferrer"><em>Vibe Coding: Building Production-Grade Software With GenAI, Chat, Agents, and Beyond</em></a> (IT Revolution, 2025)</td><td>Small tasks, guardrails and testing, with warnings about agents that delete tests or &quot;cheat&quot;. Note that Kim and Yegge use &quot;vibe coding&quot; to mean <em>disciplined</em> AI-assisted work, the opposite of Karpathy&#39;s original sense.</td><td>deep dive</td></tr></tbody></table><h2 id="free-courses" tabindex="-1">Free courses <a class="header-anchor" href="#free-courses" aria-label="Permalink to &quot;Free courses&quot;">​</a></h2><p>Good for extra practice or a different explanation. All can be started without paying; some charge for certificates or graded extras.</p><table tabindex="0"><thead><tr><th>Course</th><th>Why</th><th>Time</th></tr></thead><tbody><tr><td>Anthropic Academy, <a href="https://academy.claude.com/courses/ai-fluency-framework-foundations" target="_blank" rel="noreferrer">AI Fluency: Framework and foundations</a></td><td><strong>Week 2 homework</strong> (see <a href="#weeks-1-and-2--hello-vibe-coding--ship-your-page">weeks 1 and 2</a> above). Its companion, <a href="https://academy.claude.com/courses/ai-capabilities-and-limitations" target="_blank" rel="noreferrer">AI capabilities and limitations</a>, is a good optional follow-up on what language models can and can&#39;t do.</td><td>deep dive</td></tr><tr><td>DeepLearning.AI, <a href="https://www.deeplearning.ai/courses/build-with-andrew" target="_blank" rel="noreferrer">Build with Andrew</a></td><td>A short course on building with AI that assumes no coding or AI background. It works with any chatbot and is free to audit (the certificate costs extra). A good warm-up for week 1 if you&#39;ve never built anything with AI.</td><td>deep dive</td></tr><tr><td>Microsoft, <a href="https://developer.microsoft.com/blog/get-started-with-github-copilot-cli-a-free-hands-on-course/" target="_blank" rel="noreferrer">GitHub Copilot CLI for Beginners</a></td><td>A hands-on course that runs in GitHub Codespaces on Copilot Free, the same setup as weeks 11–16. Good preparation for the agent weeks.</td><td>deep dive</td></tr><tr><td>Google and Kaggle, <a href="https://www.kaggle.com/learn-guide/5-day-agents-vibecoding" target="_blank" rel="noreferrer">5-Day AI Agents Intensive (vibe coding edition)</a></td><td>Now a self-paced guide covering agents, tools, context, security and deployment. Uses free Kaggle and Google AI Studio accounts; AI Studio is 18+ (<a href="./../TOOLS.html">Tool Handout</a>). Signing up asks for a phone number.</td><td>deep dive</td></tr><tr><td>Microsoft and GitHub, <a href="https://developer.microsoft.com/blog/github-copilot-app-for-beginners/" target="_blank" rel="noreferrer">GitHub Copilot app for Beginners</a> (28 September 2026)</td><td><strong>Optional.</strong> Seven hands-on chapters around one sample app, each ending with a &quot;trust the evidence&quot; check: read the diff, run the tests, preview the app. It assumes you know Git and npm, and it doesn&#39;t say whether Copilot Free is enough, so it suits weeks 11–16 or after the course.</td><td>deep dive</td></tr><tr><td>DeepLearning.AI, <a href="https://www.deeplearning.ai/courses/ai-coding-workflows-from-cloud-to-local" target="_blank" rel="noreferrer">AI Coding Workflows: From Cloud to Local</a></td><td><strong>Stretch:</strong> &quot;what if my quota runs out?&quot; It rebuilds the same app with cheaper models, then through OpenRouter, then on a model running on your own computer, which needs a capable machine. Intermediate level; the graded quiz needs a paid plan.</td><td>deep dive (about 1.5 hours of video)</td></tr></tbody></table><hr><p>Want the evidence behind the course design? See <a href="./../research/design-rationale.html">Why the Course Looks Like This</a>.</p>',35)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
